--
-- Name: bump_quotation_version_on_doc_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."bump_quotation_version_on_doc_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Solo PROFORMA versiona. Si el cambio es solo de aceptaciÃ³n/estado de
  -- cobranza (o el propio bump desde Ã­tems), no se suma de nuevo.
  IF NEW.doc_type IS DISTINCT FROM 'PROFORMA' THEN RETURN NEW; END IF;
  IF NEW.client_id IS DISTINCT FROM OLD.client_id
    OR NEW.currency IS DISTINCT FROM OLD.currency
    OR COALESCE(NEW.notes, '') IS DISTINCT FROM COALESCE(OLD.notes, '')
    OR NEW.due_date IS DISTINCT FROM OLD.due_date
    OR NEW.issue_date IS DISTINCT FROM OLD.issue_date THEN
    NEW.quotation_version := COALESCE(OLD.quotation_version, 1) + 1;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."bump_quotation_version_on_doc_update"() OWNER TO "postgres";

