--
-- Name: claim_invoice_job(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_invoice_job"() RETURNS "public"."invoice_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.invoice_jobs;
begin
  update public.invoice_jobs
    set status = 'processing', locked_at = now(), attempts = attempts + 1
    where id = (
      select id from public.invoice_jobs
      where status = 'queued'
      order by created_at
      limit 1
      for update skip locked
    )
    returning * into v_job;
  return v_job;
end;
$$;


