-- Name: reject_quotation_acceptance_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reject_quotation_acceptance_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'sales_quotation_acceptances es append-only: % no permitido (id %)',
    TG_OP, COALESCE(OLD.id, NEW.id);
  RETURN NULL;
END;
$$;


