--
-- Name: scan_sessions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."scan_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "empresa_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "context_type" "text" DEFAULT 'general'::"text" NOT NULL,
    "context_id" "text",
    "target_field" "text",
    "status" "text" DEFAULT 'waiting'::"text" NOT NULL,
    "token_hash" "text" NOT NULL,
    "pin_code" "text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "claimed_by_user_id" "uuid",
    "claimed_device_info" "jsonb" DEFAULT '{}'::"jsonb",
    "storage_bucket" "text" DEFAULT 'invoice-files'::"text" NOT NULL,
    "storage_path" "text",
    "file_name" "text",
    "file_size_bytes" bigint,
    "page_count" integer DEFAULT 0,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "mobile_claim_token_hash" "text",
    "claimed_at" timestamp with time zone,
    "pin_failed_attempts" integer DEFAULT 0 NOT NULL,
    "pin_locked_until" timestamp with time zone,
    CONSTRAINT "scan_sessions_status_check" CHECK (("status" = ANY (ARRAY['waiting'::"text", 'connected'::"text", 'scanning'::"text", 'processing'::"text", 'completed'::"text", 'expired'::"text", 'canceled'::"text"])))
);


ALTER TABLE "public"."scan_sessions" OWNER TO "postgres";

--
-- Name: scan_session_claim_atomic("uuid", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."scan_session_claim_atomic"("p_session_id" "uuid", "p_mobile_claim_token_hash" "text", "p_device_info" "jsonb" DEFAULT '{}'::"jsonb", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."scan_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.scan_sessions;
begin
  update public.scan_sessions
  set status = 'connected',
      mobile_claim_token_hash = p_mobile_claim_token_hash,
      token_hash = 'CLAIMED:' || token_hash, -- Invalida QR token para cualquier operaciÃ³n futura
      claimed_device_info = coalesce(p_device_info, '{}'::jsonb),
      claimed_by_user_id = p_user_id,
      claimed_at = now()
  where id = p_session_id
    and status = 'waiting'
    and expires_at > now()
  returning * into v_session;

  return v_session;
end;
$$;


ALTER FUNCTION "public"."scan_session_claim_atomic"("p_session_id" "uuid", "p_mobile_claim_token_hash" "text", "p_device_info" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";

--
-- Name: scan_session_complete_atomic("uuid", "text", "text", bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."scan_session_complete_atomic"("p_session_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_file_size" bigint, "p_page_count" integer) RETURNS "public"."scan_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.scan_sessions;
begin
  update public.scan_sessions
  set status = 'completed',
      storage_path = p_storage_path,
      file_name = p_file_name,
      file_size_bytes = p_file_size,
      page_count = p_page_count,
      completed_at = now(),
      mobile_claim_token_hash = null -- Invalida la credencial mÃ³vil inmediatamente
  where id = p_session_id
    and status in ('connected', 'scanning', 'processing')
    and expires_at > now()
  returning * into v_session;

  return v_session;
end;
$$;


ALTER FUNCTION "public"."scan_session_complete_atomic"("p_session_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_file_size" bigint, "p_page_count" integer) OWNER TO "postgres";

--
-- Name: scan_session_create_atomic("uuid", "uuid", "text", "text", timestamp with time zone, "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."scan_session_create_atomic"("p_empresa_id" "uuid", "p_user_id" "uuid", "p_token_hash" "text", "p_pin_code" "text", "p_expires_at" timestamp with time zone, "p_context_type" "text" DEFAULT 'general'::"text", "p_context_id" "text" DEFAULT NULL::"text", "p_target_field" "text" DEFAULT NULL::"text", "p_storage_bucket" "text" DEFAULT 'invoice-files'::"text") RETURNS "public"."scan_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.scan_sessions;
begin
  -- Limpiar sesiones expiradas que puedan estar reteniendo un PIN en el Ã­ndice parcial
  update public.scan_sessions
  set status = 'expired'
  where status = 'waiting' and expires_at <= clock_timestamp();

  -- Intentar insertar la nueva sesiÃ³n (el Ã­ndice Ãºnico parcial garantiza ausencia de colisiÃ³n activa)
  insert into public.scan_sessions (
    empresa_id,
    created_by,
    token_hash,
    pin_code,
    expires_at,
    context_type,
    context_id,
    target_field,
    storage_bucket,
    status
  ) values (
    p_empresa_id,
    p_user_id,
    p_token_hash,
    p_pin_code,
    p_expires_at,
    p_context_type,
    p_context_id,
    p_target_field,
    p_storage_bucket,
    'waiting'
  )
  returning * into v_session;

  return v_session;
end;
$$;


ALTER FUNCTION "public"."scan_session_create_atomic"("p_empresa_id" "uuid", "p_user_id" "uuid", "p_token_hash" "text", "p_pin_code" "text", "p_expires_at" timestamp with time zone, "p_context_type" "text", "p_context_id" "text", "p_target_field" "text", "p_storage_bucket" "text") OWNER TO "postgres";

--
-- Name: select_and_authorize_offer_atomically("uuid", "uuid", "uuid", "uuid", "uuid", "public"."selection_reason", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."select_and_authorize_offer_atomically"("p_empresa_id" "uuid", "p_actor_id" "uuid", "p_rfq_id" "uuid", "p_rfq_provider_id" "uuid", "p_quote_version_id" "uuid", "p_selection_reason" "public"."selection_reason" DEFAULT NULL::"public"."selection_reason", "p_selection_reason_detail" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_rfq public.rfqs;
  v_rp record;
  v_quote public.quote_versions;
  v_order_id uuid;
  v_lowest_competing_price numeric;
  v_is_cheapest boolean;
BEGIN
  IF auth.uid() IS NULL
     OR p_actor_id IS DISTINCT FROM auth.uid()
     OR public.current_empresa_id() IS DISTINCT FROM p_empresa_id
     OR NOT public.is_internal_role(ARRAY['comercial','admin']::public.user_role[]) THEN
    RAISE EXCEPTION 'Acceso denegado para autorizar oferta';
  END IF;

  SELECT * INTO v_rfq FROM public.rfqs r
  WHERE r.id = p_rfq_id AND r.empresa_id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada'; END IF;

  SELECT rp.id, rp.rfq_id, rp.provider_id, p.name AS provider_name
    INTO v_rp
  FROM public.rfq_providers rp
  JOIN public.providers p ON p.id = rp.provider_id AND p.empresa_id = p_empresa_id
  WHERE rp.id = p_rfq_provider_id AND rp.rfq_id = p_rfq_id
    AND rp.empresa_id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proveedor no encontrado en esta solicitud'; END IF;

  SELECT qv.* INTO v_quote
  FROM public.quote_versions qv
  JOIN public.quotes q ON q.id = qv.quote_id AND q.empresa_id = p_empresa_id
  WHERE qv.id = p_quote_version_id AND qv.empresa_id = p_empresa_id
    AND q.rfq_provider_id = p_rfq_provider_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'CotizaciÃ³n no encontrada para este proveedor y solicitud'; END IF;
  IF v_quote.version_number <> (
    SELECT max(qv_latest.version_number)
    FROM public.quote_versions qv_latest
    WHERE qv_latest.quote_id = v_quote.quote_id AND qv_latest.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'Solo se puede autorizar la Ãºltima versiÃ³n de la cotizaciÃ³n';
  END IF;

  IF v_rfq.status = 'AUTORIZADO' THEN
    SELECT ao.id INTO v_order_id
    FROM public.authorized_orders ao
    WHERE ao.rfq_id = p_rfq_id AND ao.empresa_id = p_empresa_id
      AND ao.created_from = 'rfq'
      AND ao.provider_id = v_rp.provider_id
      AND ao.quote_version_id = p_quote_version_id
    ORDER BY ao.created_at DESC
    LIMIT 1;
    IF v_order_id IS NOT NULL AND v_rfq.selected_rfq_provider_id = p_rfq_provider_id THEN
      RETURN v_order_id;
    END IF;
    RAISE EXCEPTION 'La solicitud ya tiene otra oferta autorizada';
  END IF;
  IF v_rfq.status NOT IN ('COTIZANDO','OFERTAS_RECIBIDAS') THEN
    RAISE EXCEPTION 'La solicitud estÃ¡ cerrada o no admite autorizaciÃ³n';
  END IF;

  SELECT min(qv_comp.total_price) INTO v_lowest_competing_price
  FROM public.rfq_providers rp_comp
  JOIN public.quotes q_comp ON q_comp.rfq_provider_id = rp_comp.id
    AND q_comp.empresa_id = p_empresa_id
  JOIN public.quote_versions qv_comp ON qv_comp.quote_id = q_comp.id
    AND qv_comp.empresa_id = p_empresa_id
    AND qv_comp.version_number = (
      SELECT max(qv_latest.version_number)
      FROM public.quote_versions qv_latest
      WHERE qv_latest.quote_id = q_comp.id AND qv_latest.empresa_id = p_empresa_id
    )
  WHERE rp_comp.rfq_id = p_rfq_id AND rp_comp.empresa_id = p_empresa_id
    AND rp_comp.id <> p_rfq_provider_id
    AND qv_comp.currency = v_quote.currency;

  v_is_cheapest := v_lowest_competing_price IS NULL
    OR v_quote.total_price <= v_lowest_competing_price;
  IF NOT v_is_cheapest AND p_selection_reason IS NULL THEN
    RAISE EXCEPTION 'La oferta no es la mÃ¡s econÃ³mica: se requiere motivo de selecciÃ³n';
  END IF;

  INSERT INTO public.authorized_orders (
    empresa_id, rfq_id, provider_id, quote_version_id, created_from,
    provider_name, client_name, product, quantity, unit, unit_price,
    total_price, currency, vat_included, authorized_by, is_cheapest,
    selection_reason, selection_reason_detail, project_id
  ) VALUES (
    p_empresa_id, v_rfq.id, v_rp.provider_id, v_quote.id, 'rfq',
    v_rp.provider_name, v_rfq.client_name, v_rfq.product, v_rfq.quantity, v_rfq.unit,
    v_quote.unit_price, v_quote.total_price, v_quote.currency, v_quote.vat_included,
    p_actor_id, v_is_cheapest,
    CASE WHEN v_is_cheapest THEN NULL ELSE p_selection_reason END,
    CASE WHEN v_is_cheapest THEN NULL ELSE nullif(pg_catalog.btrim(p_selection_reason_detail), '') END,
    v_rfq.project_id
  ) RETURNING id INTO v_order_id;

  UPDATE public.rfqs r
  SET status = 'AUTORIZADO', selected_rfq_provider_id = p_rfq_provider_id,
      updated_at = pg_catalog.now()
  WHERE r.id = p_rfq_id AND r.empresa_id = p_empresa_id
    AND r.status IN ('COTIZANDO','OFERTAS_RECIBIDAS');
  IF NOT FOUND THEN RAISE EXCEPTION 'La solicitud cambiÃ³ durante la autorizaciÃ³n'; END IF;
  RETURN v_order_id;
END;
$$;


ALTER FUNCTION "public"."select_and_authorize_offer_atomically"("p_empresa_id" "uuid", "p_actor_id" "uuid", "p_rfq_id" "uuid", "p_rfq_provider_id" "uuid", "p_quote_version_id" "uuid", "p_selection_reason" "public"."selection_reason", "p_selection_reason_detail" "text") OWNER TO "postgres";

--
-- Name: set_agent_approvals_empresa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_agent_approvals_empresa"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_empresa uuid;
begin
  if new.empresa_id is null then
    select empresa_id into v_empresa from public.agent_tasks where id = new.task_id;
    new.empresa_id := coalesce(v_empresa, public.current_empresa_id());
  end if;
  if new.empresa_id is null then
    raise exception 'agent_approvals.empresa_id is required';
  end if;
  select empresa_id into v_empresa from public.agent_tasks where id = new.task_id;
  if v_empresa is distinct from new.empresa_id then
    raise exception 'agent_approvals empresa_id does not match task empresa_id';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."set_agent_approvals_empresa"() OWNER TO "postgres";

--
-- Name: set_agent_runs_empresa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_agent_runs_empresa"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_empresa uuid;
begin
  if new.empresa_id is null then
    select empresa_id into v_empresa from public.agent_tasks where id = new.task_id;
    new.empresa_id := coalesce(v_empresa, public.current_empresa_id());
  end if;
  if new.empresa_id is null then
    raise exception 'agent_runs.empresa_id is required';
  end if;
  -- validar que empresa del run coincida con la del task (anti cross-tenant link)
  select empresa_id into v_empresa from public.agent_tasks where id = new.task_id;
  if v_empresa is not null and v_empresa is distinct from new.empresa_id then
    raise exception 'agent_runs empresa_id % does not match task empresa_id %', new.empresa_id, v_empresa;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."set_agent_runs_empresa"() OWNER TO "postgres";

