  v_eid uuid;
begin
  if new.code is null then
    v_eid := coalesce(
      new.empresa_id,
      (select empresa_id from public.rfqs where id = new.rfq_id),
      public.current_empresa_id()
    );
    new.code := public.next_doc_code(v_eid, 'OC');
  end if;
  return new;
