--
-- Name: set_work_order_item_empresa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_work_order_item_empresa"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.empresa_id IS NULL THEN
    NEW.empresa_id := COALESCE(
      (SELECT empresa_id FROM public.work_orders WHERE id = NEW.work_order_id),
      public.current_empresa_id());
  END IF;
  RETURN NEW;
END;
$$;


