--
-- Name: upsert_inventory_balance("uuid", "uuid", "uuid", "public"."currency_code", numeric, numeric, numeric, "text", "text", numeric, numeric, numeric, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."upsert_inventory_balance"("p_empresa_id" "uuid", "p_producto_id" "uuid", "p_location_id" "uuid", "p_cost_currency" "public"."currency_code", "p_quantity" numeric, "p_total_cost" numeric, "p_total_cost_company" numeric, "p_cost_status" "text", "p_original_cost_currency" "text" DEFAULT NULL::"text", "p_original_unit_cost" numeric DEFAULT NULL::numeric, "p_original_total_cost" numeric DEFAULT NULL::numeric, "p_exchange_rate_to_company" numeric DEFAULT NULL::numeric, "p_cost_source" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'El saldo a agregar debe ser positivo';
  END IF;

  IF p_cost_status = 'COMPUTABLE' THEN
    IF p_cost_currency IS NULL
       OR p_total_cost IS NULL
       OR p_total_cost_company IS NULL
       OR p_exchange_rate_to_company IS NULL
       OR p_exchange_rate_to_company <= 0 THEN
      RAISE EXCEPTION 'Un saldo computable necesita costo, moneda y FX vÃ¡lidos';
    END IF;

    INSERT INTO public.inventory_balances (
      empresa_id, producto_id, location_id, cost_currency, quantity,
      total_cost, total_cost_company, cost_status, original_cost_currency,
      original_unit_cost, original_total_cost, exchange_rate_to_company,
      cost_source
    ) VALUES (
      p_empresa_id, p_producto_id, p_location_id, p_cost_currency, p_quantity,
      p_total_cost, p_total_cost_company, 'COMPUTABLE',
      p_original_cost_currency, p_original_unit_cost, p_original_total_cost,
      p_exchange_rate_to_company, coalesce(p_cost_source, 'CANONICAL_MOVEMENT')
    )
    ON CONFLICT (empresa_id, producto_id, location_id, cost_currency)
    DO UPDATE SET
      quantity = public.inventory_balances.quantity + EXCLUDED.quantity,
      total_cost = public.inventory_balances.total_cost + EXCLUDED.total_cost,
      total_cost_company = public.inventory_balances.total_cost_company
        + EXCLUDED.total_cost_company,
      exchange_rate_to_company = CASE
        WHEN public.inventory_balances.total_cost + EXCLUDED.total_cost = 0
          THEN EXCLUDED.exchange_rate_to_company
        ELSE (public.inventory_balances.total_cost_company
              + EXCLUDED.total_cost_company)
          / (public.inventory_balances.total_cost + EXCLUDED.total_cost)
      END,
      original_cost_currency = coalesce(
        public.inventory_balances.original_cost_currency,
        EXCLUDED.original_cost_currency
      ),
      original_unit_cost = coalesce(
        public.inventory_balances.original_unit_cost,
        EXCLUDED.original_unit_cost
      ),
      original_total_cost = coalesce(
        public.inventory_balances.original_total_cost,
        0
      ) + coalesce(EXCLUDED.original_total_cost, 0),
      cost_source = coalesce(EXCLUDED.cost_source, public.inventory_balances.cost_source),
      updated_at = now();
    RETURN;
  END IF;

  IF p_cost_status = 'REVISION_REQUERIDA' THEN
    INSERT INTO public.inventory_balances (
      empresa_id, producto_id, location_id, cost_currency, quantity,
      total_cost, total_cost_company, cost_status, original_cost_currency,
      original_unit_cost, original_total_cost, exchange_rate_to_company,
      cost_source
    ) VALUES (
      p_empresa_id, p_producto_id, p_location_id, NULL, p_quantity,
      NULL, NULL, 'REVISION_REQUERIDA', p_original_cost_currency,
      p_original_unit_cost, p_original_total_cost, NULL,
      coalesce(p_cost_source, 'CANONICAL_MOVEMENT_REVIEW')
    )
    ON CONFLICT (empresa_id, producto_id, location_id) WHERE cost_currency IS NULL
    DO UPDATE SET
      quantity = public.inventory_balances.quantity + EXCLUDED.quantity,
      total_cost = NULL,
      total_cost_company = NULL,
      cost_status = 'REVISION_REQUERIDA',
      original_cost_currency = CASE
        WHEN public.inventory_balances.original_cost_currency IS NULL
          THEN EXCLUDED.original_cost_currency
        WHEN EXCLUDED.original_cost_currency IS NULL
          OR public.inventory_balances.original_cost_currency = EXCLUDED.original_cost_currency
          THEN public.inventory_balances.original_cost_currency
        ELSE 'MULTIPLE'
      END,
      original_unit_cost = CASE
        WHEN public.inventory_balances.original_cost_currency IS NOT DISTINCT FROM
             EXCLUDED.original_cost_currency
          THEN coalesce(public.inventory_balances.original_unit_cost,
                        EXCLUDED.original_unit_cost)
        ELSE NULL
      END,
      original_total_cost = CASE
        WHEN public.inventory_balances.original_cost_currency IS NOT DISTINCT FROM
             EXCLUDED.original_cost_currency
          THEN coalesce(public.inventory_balances.original_total_cost, 0)
             + coalesce(EXCLUDED.original_total_cost, 0)
        ELSE NULL
      END,
      exchange_rate_to_company = NULL,
      cost_source = coalesce(EXCLUDED.cost_source, public.inventory_balances.cost_source),
      updated_at = now();
    RETURN;
  END IF;

  RAISE EXCEPTION 'Estado de costo invÃ¡lido: %', p_cost_status;
END;
$$;


ALTER FUNCTION "public"."upsert_inventory_balance"("p_empresa_id" "uuid", "p_producto_id" "uuid", "p_location_id" "uuid", "p_cost_currency" "public"."currency_code", "p_quantity" numeric, "p_total_cost" numeric, "p_total_cost_company" numeric, "p_cost_status" "text", "p_original_cost_currency" "text", "p_original_unit_cost" numeric, "p_original_total_cost" numeric, "p_exchange_rate_to_company" numeric, "p_cost_source" "text") OWNER TO "postgres";

--
-- Name: validate_inventory_balance_tenant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_inventory_balance_tenant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_empresa_producto uuid;
  v_empresa_location uuid;
BEGIN
  SELECT empresa_id INTO v_empresa_producto FROM public.productos WHERE id = NEW.producto_id;
  SELECT empresa_id INTO v_empresa_location FROM public.inventory_locations WHERE id = NEW.location_id;
  IF v_empresa_producto IS NULL OR v_empresa_location IS NULL
     OR v_empresa_producto IS DISTINCT FROM NEW.empresa_id
     OR v_empresa_location IS DISTINCT FROM NEW.empresa_id THEN
    RAISE EXCEPTION 'El saldo referencia datos de otro tenant';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_inventory_balance_tenant"() OWNER TO "postgres";

--
-- Name: validate_inventory_location_tenant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_inventory_location_tenant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_empresa uuid;
BEGIN
  IF auth.role() <> 'service_role'
     AND (public.current_empresa_id() IS NULL OR public.current_empresa_id() IS DISTINCT FROM NEW.empresa_id) THEN
    RAISE EXCEPTION 'La ubicaciÃ³n no pertenece al tenant de la sesiÃ³n';
  END IF;

  IF NEW.project_id IS NOT NULL THEN
    SELECT empresa_id INTO v_empresa FROM public.projects WHERE id = NEW.project_id;
    IF v_empresa IS NULL OR v_empresa IS DISTINCT FROM NEW.empresa_id THEN
      RAISE EXCEPTION 'El proyecto no pertenece a la empresa de la ubicaciÃ³n';
    END IF;
  END IF;

  IF NEW.parent_location_id IS NOT NULL THEN
    SELECT empresa_id INTO v_empresa
    FROM public.inventory_locations WHERE id = NEW.parent_location_id;
    IF v_empresa IS NULL OR v_empresa IS DISTINCT FROM NEW.empresa_id THEN
      RAISE EXCEPTION 'La ubicaciÃ³n padre no pertenece a la misma empresa';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_inventory_location_tenant"() OWNER TO "postgres";

