    CONSTRAINT "inventory_balances_cost_status_check" CHECK (("cost_status" = ANY (ARRAY['COMPUTABLE'::"text", 'REVISION_REQUERIDA'::"text"]))),
    CONSTRAINT "inventory_balances_exchange_rate_to_company_check" CHECK ((("exchange_rate_to_company" IS NULL) OR ("exchange_rate_to_company" > (0)::numeric))),
    CONSTRAINT "inventory_balances_quantity_check" CHECK (("quantity" >= (0)::numeric)),
    CONSTRAINT "inventory_balances_total_cost_check" CHECK (("total_cost" >= (0)::numeric))
);


