    CONSTRAINT "inventory_movement_costs_exchange_rate_to_company_check" CHECK ((("exchange_rate_to_company" IS NULL) OR ("exchange_rate_to_company" > (0)::numeric))),
    CONSTRAINT "inventory_movement_costs_quantity_check" CHECK (("quantity" > (0)::numeric)),
    CONSTRAINT "inventory_movement_costs_total_cost_check" CHECK (("total_cost" >= (0)::numeric)),
    CONSTRAINT "inventory_movement_costs_unit_cost_check" CHECK (("unit_cost" >= (0)::numeric))
);


