--
-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."inventory_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "empresa_id" "uuid" NOT NULL,
    "producto_id" "uuid" NOT NULL,
    "quantity" numeric(18,4) NOT NULL,
    "unit" "text" NOT NULL,
    "movement_type" "text" NOT NULL,
    "from_location_id" "uuid",
    "to_location_id" "uuid",
    "project_id" "uuid",
    "budget_item_id" "uuid",
    "source_type" "text" DEFAULT 'MANUAL'::"text" NOT NULL,
    "source_id" "uuid",
    "source_line_id" "uuid",
    "status" "text" DEFAULT 'CONFIRMED'::"text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "cost_currency" "public"."currency_code",
    "unit_cost" numeric(20,6),
    "cost_total" numeric(20,6),
    "exchange_rate_to_company" numeric(20,8),
    "cost_total_company" numeric(20,6),
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "confirmed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "confirmed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cost_status" "text" DEFAULT 'COMPUTABLE'::"text" NOT NULL,
    CONSTRAINT "inventory_movements_consumption_budget_check" CHECK ((("movement_type" = 'CONSUMPTION'::"text") OR ("budget_item_id" IS NULL))),
    CONSTRAINT "inventory_movements_cost_status_check" CHECK (("cost_status" = ANY (ARRAY['COMPUTABLE'::"text", 'REVISION_REQUERIDA'::"text"]))),
    CONSTRAINT "inventory_movements_exchange_rate_to_company_check" CHECK ((("exchange_rate_to_company" IS NULL) OR ("exchange_rate_to_company" > (0)::numeric))),
    CONSTRAINT "inventory_movements_idempotency_key_check" CHECK (("length"(TRIM(BOTH FROM "idempotency_key")) > 0)),
    CONSTRAINT "inventory_movements_movement_type_check" CHECK (("movement_type" = ANY (ARRAY['RECEIPT'::"text", 'TRANSFER'::"text", 'CONSUMPTION'::"text", 'RETURN'::"text", 'ADJUSTMENT'::"text"]))),
    CONSTRAINT "inventory_movements_quantity_check" CHECK (("quantity" <> (0)::numeric)),
    CONSTRAINT "inventory_movements_shape_check" CHECK (((("movement_type" = 'RECEIPT'::"text") AND ("from_location_id" IS NULL) AND ("to_location_id" IS NOT NULL) AND ("quantity" > (0)::numeric)) OR (("movement_type" = 'TRANSFER'::"text") AND ("from_location_id" IS NOT NULL) AND ("to_location_id" IS NOT NULL) AND ("from_location_id" <> "to_location_id") AND ("quantity" > (0)::numeric)) OR (("movement_type" = 'CONSUMPTION'::"text") AND ("from_location_id" IS NOT NULL) AND ("to_location_id" IS NULL) AND ("quantity" > (0)::numeric) AND ("project_id" IS NOT NULL) AND ("budget_item_id" IS NOT NULL)) OR (("movement_type" = 'RETURN'::"text") AND ("from_location_id" IS NOT NULL) AND ("to_location_id" IS NOT NULL) AND ("from_location_id" <> "to_location_id") AND ("quantity" > (0)::numeric)) OR (("movement_type" = 'ADJUSTMENT'::"text") AND ((("quantity" > (0)::numeric) AND ("from_location_id" IS NULL) AND ("to_location_id" IS NOT NULL)) OR (("quantity" < (0)::numeric) AND ("from_location_id" IS NOT NULL) AND ("to_location_id" IS NULL)))))),
    CONSTRAINT "inventory_movements_status_check" CHECK (("status" = ANY (ARRAY['DRAFT'::"text", 'CONFIRMED'::"text", 'VOIDED'::"text"]))),
    CONSTRAINT "inventory_movements_unit_check" CHECK (("length"(TRIM(BOTH FROM "unit")) > 0)),
    CONSTRAINT "inventory_movements_unit_cost_check" CHECK ((("unit_cost" IS NULL) OR ("unit_cost" >= (0)::numeric)))
);


ALTER TABLE "public"."inventory_movements" OWNER TO "postgres";

