--
-- Name: inventory_consumption_by_budget; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_consumption_by_budget" WITH ("security_invoker"='true') AS
 SELECT "m"."empresa_id",
    "m"."project_id",
    "m"."budget_item_id",
    "m"."producto_id",
    "p"."nombre" AS "producto",
    "p"."unidad",
    "sum"("c"."quantity") AS "quantity_consumed",
    "c"."cost_currency",
    "sum"("c"."total_cost") AS "cost_consumed",
    "sum"("c"."total_cost_company") AS "cost_consumed_company"
   FROM (("public"."inventory_movements" "m"
     JOIN "public"."productos" "p" ON (("p"."id" = "m"."producto_id")))
     JOIN "public"."inventory_movement_costs" "c" ON (("c"."movement_id" = "m"."id")))
  WHERE (("m"."movement_type" = 'CONSUMPTION'::"text") AND ("m"."status" = 'CONFIRMED'::"text") AND ("c"."cost_status" = 'COMPUTABLE'::"text"))
  GROUP BY "m"."empresa_id", "m"."project_id", "m"."budget_item_id", "m"."producto_id", "p"."nombre", "p"."unidad", "c"."cost_currency";


ALTER VIEW "public"."inventory_consumption_by_budget" OWNER TO "postgres";

