--
-- Name: inventory_stock_by_location; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_stock_by_location" WITH ("security_invoker"='true') AS
 SELECT "b"."empresa_id",
    "b"."location_id",
    "l"."name" AS "location_name",
    "l"."location_type",
    "l"."project_id",
    "b"."producto_id",
    "p"."nombre" AS "producto",
    "p"."unidad",
    "b"."cost_currency",
    "b"."quantity",
    "b"."total_cost",
    "b"."cost_status",
    "b"."original_cost_currency",
    "b"."original_unit_cost",
    "b"."original_total_cost",
    "b"."exchange_rate_to_company",
    "b"."cost_source",
    "b"."updated_at",
    "b"."total_cost_company"
   FROM (("public"."inventory_balances" "b"
     JOIN "public"."inventory_locations" "l" ON (("l"."id" = "b"."location_id")))
     JOIN "public"."productos" "p" ON (("p"."id" = "b"."producto_id")))
  WHERE ("b"."quantity" > (0)::numeric);


ALTER VIEW "public"."inventory_stock_by_location" OWNER TO "postgres";

--
-- Name: inventory_stock_by_project; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_stock_by_project" WITH ("security_invoker"='true') AS
 SELECT "empresa_id",
    "project_id",
    "producto_id",
    "producto",
    "unidad",
    "cost_currency",
    "cost_status",
    "sum"("quantity") AS "quantity",
    "sum"("total_cost") AS "total_cost",
    "sum"("total_cost_company") AS "total_cost_company"
   FROM "public"."inventory_stock_by_location"
  WHERE ("project_id" IS NOT NULL)
  GROUP BY "empresa_id", "project_id", "producto_id", "producto", "unidad", "cost_currency", "cost_status";


ALTER VIEW "public"."inventory_stock_by_project" OWNER TO "postgres";

--
-- Name: inventory_stock_global; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_stock_global" WITH ("security_invoker"='true') AS
 SELECT "empresa_id",
    "producto_id",
    "producto",
    "unidad",
    "cost_currency",
    "sum"("quantity") AS "quantity",
    "sum"("total_cost") AS "total_cost",
    "sum"("total_cost_company") AS "total_cost_company"
   FROM "public"."inventory_stock_by_location"
  WHERE (("cost_status" = 'COMPUTABLE'::"text") AND ("cost_currency" IS NOT NULL))
  GROUP BY "empresa_id", "producto_id", "producto", "unidad", "cost_currency";


ALTER VIEW "public"."inventory_stock_global" OWNER TO "postgres";

--
-- Name: inventory_stock_global_quantity; Type: VIEW; Schema: public; Owner: postgres
