--
-- Name: project_certificates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."project_certificates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "numero" integer NOT NULL,
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "status" "text" DEFAULT 'BORRADOR'::"text" NOT NULL,
    "monto_anterior" numeric(18,2) DEFAULT 0 NOT NULL,
    "monto_presente" numeric(18,2) DEFAULT 0 NOT NULL,
    "monto_acumulado" numeric(18,2) GENERATED ALWAYS AS (("monto_anterior" + "monto_presente")) STORED,
    "notes" "text",
    "created_by" "uuid",
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ajustes" numeric(18,2) DEFAULT 0 NOT NULL,
    "devolucion_anticipo" numeric(18,2) DEFAULT 0 NOT NULL,
    "retencion" numeric(18,2) DEFAULT 0 NOT NULL,
    "penalidad_avance" numeric(18,2) DEFAULT 0 NOT NULL,
    "penalidad_presentacion" numeric(18,2) DEFAULT 0 NOT NULL,
    "devolucion_anticipo_pct_snap" numeric(5,2),
    "retencion_pct_snap" numeric(5,2),
    "elaborado_por" "uuid",
    "elaborado_at" timestamp with time zone,
    "verificado_por" "uuid",
    "verificado_at" timestamp with time zone,
    "aprobado_por" "uuid",
    "aprobado_at" timestamp with time zone,
    "facturado_at" timestamp with time zone,
    "factura_numero" "text",
    "monto_liquido" numeric(18,2) GENERATED ALWAYS AS (((((("monto_presente" + "ajustes") - "devolucion_anticipo") - "retencion") - "penalidad_avance") - "penalidad_presentacion")) STORED,
    "import_fingerprint" "text",
    CONSTRAINT "project_certificates_check" CHECK (("period_end" >= "period_start")),
    CONSTRAINT "project_certificates_status_check" CHECK (("status" = ANY (ARRAY['BORRADOR'::"text", 'ELABORADO'::"text", 'VERIFICADO'::"text", 'APROBADO'::"text", 'FACTURADO'::"text"])))
);


