--
-- Name: stock_por_proyecto; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."stock_por_proyecto" WITH ("security_invoker"='true') AS
 SELECT "m"."empresa_id",
    "m"."project_id",
    "m"."producto_id",
    "p"."nombre" AS "producto",
    "p"."unidad",
    "p"."costo_promedio",
    "sum"(
        CASE
            WHEN ("m"."tipo" = 'ENTRADA'::"text") THEN "m"."cantidad"
            ELSE (0)::numeric
        END) AS "qty_comprada",
    "sum"(
        CASE
            WHEN ("m"."tipo" = 'SALIDA'::"text") THEN "m"."cantidad"
            ELSE (0)::numeric
        END) AS "qty_consumida",
    "sum"(
        CASE
            WHEN ("m"."tipo" = 'ENTRADA'::"text") THEN "m"."cantidad"
            WHEN ("m"."tipo" = 'SALIDA'::"text") THEN (- "m"."cantidad")
            ELSE (0)::numeric
        END) AS "qty_disponible",
    "sum"(
        CASE
            WHEN ("m"."tipo" = 'ENTRADA'::"text") THEN COALESCE("m"."costo_total", (0)::numeric)
            ELSE (0)::numeric
        END) AS "costo_comprado",
    "sum"(
        CASE
            WHEN ("m"."tipo" = 'SALIDA'::"text") THEN COALESCE((- "m"."costo_total"), (0)::numeric)
            ELSE (0)::numeric
        END) AS "costo_consumido"
   FROM ("public"."stock_movimientos" "m"
     JOIN "public"."productos" "p" ON (("p"."id" = "m"."producto_id")))
  WHERE (("m"."project_id" IS NOT NULL) AND ("m"."tipo" = ANY (ARRAY['ENTRADA'::"text", 'SALIDA'::"text"])))
  GROUP BY "m"."empresa_id", "m"."project_id", "m"."producto_id", "p"."nombre", "p"."unidad", "p"."costo_promedio";


ALTER VIEW "public"."stock_por_proyecto" OWNER TO "postgres";

