    "net_payable" numeric(18,2) GENERATED ALWAYS AS ((COALESCE("approved_amount", (0)::numeric) - "round"(((COALESCE("approved_amount", (0)::numeric) * "retention_pct") / (100)::numeric), 2))) STORED,
    "status" "text" DEFAULT 'PENDIENTE'::"text" NOT NULL,
