    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "subcontractor_certificates_approved_amount_check" CHECK ((("approved_amount" IS NULL) OR ("approved_amount" >= (0)::numeric))),
    CONSTRAINT "subcontractor_certificates_approved_pct_check" CHECK ((("approved_pct" IS NULL) OR (("approved_pct" >= (0)::numeric) AND ("approved_pct" <= (100)::numeric)))),
    CONSTRAINT "subcontractor_certificates_claimed_amount_check" CHECK (("claimed_amount" >= (0)::numeric)),
    CONSTRAINT "subcontractor_certificates_claimed_pct_check" CHECK ((("claimed_pct" >= (0)::numeric) AND ("claimed_pct" <= (100)::numeric))),
