--
-- Name: empresas admin actualiza su empresa; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "admin actualiza su empresa" ON "public"."empresas" FOR UPDATE USING ((("id" = "public"."current_empresa_id"()) AND (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))))) WITH CHECK (("id" = "public"."current_empresa_id"()));


