-- Application-specific policies and Realtime membership captured from production catalogs.
SET search_path = public, extensions, storage, pg_catalog;
CREATE POLICY bim_models_storage_delete ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'bim-models'::text) AND ((storage.foldername(name))[1] IN ( SELECT (projects.id)::text AS id
   FROM projects
  WHERE (projects.empresa_id = current_empresa_id()))) AND is_internal_role(ARRAY['administracion'::user_role, 'admin'::user_role])));
CREATE POLICY bim_models_storage_insert ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'bim-models'::text) AND ((storage.foldername(name))[1] IN ( SELECT (projects.id)::text AS id
   FROM projects
  WHERE (projects.empresa_id = current_empresa_id()))) AND is_internal_role(ARRAY['administracion'::user_role, 'admin'::user_role])));
CREATE POLICY bim_models_storage_select ON storage.objects AS PERMISSIVE FOR SELECT TO public USING (((bucket_id = 'bim-models'::text) AND ((storage.foldername(name))[1] IN ( SELECT (projects.id)::text AS id
   FROM projects
  WHERE (projects.empresa_id = current_empresa_id()))) AND is_internal_role(ARRAY['administracion'::user_role, 'admin'::user_role])));
